def converter_decisoes_json(apps, schema_editor):
    Obrigacao = apps.get_model("sales", "ObrigacaoEstoquePedido")
    Movimento = apps.get_model("stock", "MovimentoEstoque")
    Alocacao = apps.get_model("stock", "AlocacaoEvidenciaEstoque")
    Usuario = apps.get_model(*settings.AUTH_USER_MODEL.split("."))

    claims = {}
    for obrigacao in Obrigacao.objects.all().iterator():
        detalhe = dict(obrigacao.evidencia_detalhe or {})
        for entrada in detalhe.get("conciliacoes", []):
            if not isinstance(entrada, dict):
                continue
            if entrada.get("decisao") != "atribuir":
                continue
            try:
                movimento_id = int(entrada.get("movimento_id"))
            except (TypeError, ValueError):
                continue
            claims.setdefault(movimento_id, []).append(
                (obrigacao, entrada)
            )

    conflitos = 0
    criadas = 0
    for movimento_id, pedidos in claims.items():
        movimento = Movimento.objects.filter(pk=movimento_id).first()
        validos = []
        if movimento is not None and movimento.obrigacao_id is None:
            if (
                movimento.tipo in ("baixa_definitiva", "saida")
                and movimento.delta < 0
            ):
                for obrigacao, entrada in pedidos:
                    try:
                        quantidade_claim = Decimal(
                            str(entrada.get("quantidade"))
                        )
                    except (ArithmeticError, TypeError, ValueError):
                        continue
                    if quantidade_claim != abs(movimento.delta):
                        continue
                    if (
                        obrigacao.produto_id == movimento.produto_id
                        and obrigacao.unidade_id == movimento.unidade_id
                    ):
                        validos.append((obrigacao, entrada))

        existente = Alocacao.objects.filter(
            movimento_id=movimento_id
        ).first()
        if len(validos) == 1 and len(pedidos) == 1:
            obrigacao, entrada = validos[0]
            if existente is None:
                usuario_id = entrada.get("usuario_id")
                try:
                    usuario_id = (
                        int(usuario_id) if usuario_id is not None else None
                    )
                except (TypeError, ValueError):
                    usuario_id = None
                if usuario_id is not None and not Usuario.objects.filter(
                    pk=usuario_id
                ).exists():
                    usuario_id = None
                Alocacao.objects.create(
                    movimento_id=movimento_id,
                    obrigacao_id=obrigacao.pk,
                    quantidade=abs(movimento.delta),
                    usuario_id=usuario_id,
                    justificativa=entrada.get("justificativa", ""),
                )
                criadas += 1
                continue
            if existente.obrigacao_id == obrigacao.pk:
                continue

        conflitos += 1
        ids = sorted({obrigacao.pk for obrigacao, _ in pedidos})
        for obrigacao, _ in pedidos:
            detalhe = dict(obrigacao.evidencia_detalhe or {})
            conflitos_existentes = list(
                detalhe.get("conflitos_alocacao", [])
            )
            if movimento_id not in conflitos_existentes:
                conflitos_existentes.append(movimento_id)
            detalhe["conflitos_alocacao"] = conflitos_existentes
            obrigacao.evidencia_detalhe = detalhe
            obrigacao.status = "pendente"
            obrigacao.tipo_pendencia = "ambigua"
            obrigacao.quantidade_baixada = 0
            obrigacao.evidencia_baixada = 0
            obrigacao.motivo_pendencia = (
                "conflito de alocação histórica; revisar movimento "
                f"{movimento_id} e obrigações {ids}"
            )[:1000]
            obrigacao.resolvido_em = None
            obrigacao.resolvido_por = None
            obrigacao.save(
                update_fields=[
                    "evidencia_detalhe",
                    "status",
                    "tipo_pendencia",
                    "quantidade_baixada",
                    "evidencia_baixada",
                    "motivo_pendencia",
                    "resolvido_em",
                    "resolvido_por",
                    "atualizado_em",
                ]
            )

    if criadas or conflitos:
        print(
            f"AlocacaoEvidenciaEstoque: criadas={criadas} "
            f"conflitos={conflitos}"
        )


